from pathlib import Path
import ast,hashlib,json
W=Path(__file__).resolve().parent;S=W/'stage';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
cfg=json.loads((S/'configuraciones/EPISODIOS.json').read_bytes());idx=json.loads((S/'almacen/INDICE.json').read_bytes());records=[]
specs=[('M306','Integración y continuación de un objetivo APD03','Un objetivo con un paso pendiente exacto continúa mediante su journal y estado físico; después se utiliza el panel de relaciones previas y nuevas de la misma vida.','APD03',[2,3,4,5,6,7,8,10,11,12]),('M307','Sensor, léxico y consecuencias compartidas APD04','Un mismo padre recibe diez oportunidades y consecuencias intactas u omitidas; se conservan el sensor y léxico comunes, elecciones WAIT/INSPECT y efectos materiales registrados.','APD04',[1,2,3,4,5,6,7,8,10,11,12]),('M308','Retención sin tareas y transducción de versiones APD05','Desde la semilla funcional completa se reproducen8192ticks sin tareas ni sondas, seguidos del primer panel material de seis formas y dos funciones. La transducción del esquema de transporte es preparada y declarada.','APD05',[1,2,3,4,5,10,11,12])]
for ident,name,fn,campaign,wf in specs:
    plans=[x for x in cfg['plans'] if x['mechanism']==ident]
    records.append({'id':ident,'name':name,'function':fn,'campaigns':[campaign],'word_families':wf,
      'variants':[{'id':x['id'],'role':'episodio histórico completo desde padre emparejado, no vida reiniciada','initial_tick':x['initial_physical']['tick'],'final_tick':x['final_physical']['tick'],'literal_operations':len(x['operations']),'scope':x['scope']} for x in plans],
      'native':{'command':['{python}','sectores/apd_extra/ejecutar.py','--mechanism',ident,'--out','{out}'],'timeout_seconds':4800,'result':'RESULTADO.json'},'recalc':None,
      'source_files':[{'original':'Pares completos y primarios originales de'+campaign,'relative':'sectores/apd_extra/almacen/INDICE.json','sha256':sha(S/'almacen/INDICE.json'),'scope':'Cada miembro conserva hash y ubicación original; no se anidan distribuciones ni se omitió SQLite/outbox del estado operativo.'},{'original':'Operaciones literales y fronteras de tick registradas en las ejecuciones cerradas','relative':'sectores/apd_extra/configuraciones/EPISODIOS.json','sha256':sha(S/'configuraciones/EPISODIOS.json')}],
      'expected':{'comparison':'Se conserva el padre completo: RAW, clocks, interfaces, agenda y journalSQLite. Se comparan fronteras de operaciones, emisionesRAW/campos de lector ydecisiones con decoder fijo, más el estado físico final completo. Los metadatos documentales de vida/proceso/rutas se distinguen de la física.','historical_runtime_minutes':2 if ident=='M306' else 12 if ident=='M307' else 5},
      'history_status':'POSITIVO_HISTORICO_ACOTADO_CON_CONTROLES_ARCHIVADOS','integrity_status':'ESTADOS_EMPAREJADOS_FUENTES_Y_PRIMARIOS_RECUPERADOS','current_validation':'PENDIENTE_ZIP_FINAL','pending':[],
      'assistance':'El operador ofrece el currículo literal; se reproduce su calendario de ticks registrado para suprimir variación de cadencia del anfitrión. No se entrega una respuesta, ruta, signo o acción esperada al actor. Las fuentes/sensores/actuadores y decodificadores son preparación externa.',
      'limitations':['No reproduce de nuevo las ventanas de una hora ni utiliza tiempo acelerado como nueva prueba de duración.','Las historias son las mismas genealogías históricas dependientes, no nuevas réplicas independientes.','Conservar una asociación y actuar no establece política general competente, lenguaje general niR2.','Los controles adversos y resultados negativos completos permanecen en sectores/apd/archivo; no se reinterpretan como éxito por reproducir un episodio positivo.']})
for p in S.rglob('*.py'):ast.parse(p.read_bytes(),str(p))
result={'sector':'apd_extra','stage_root':str(S),'mechanisms':records,'materialized_index':idx,'notes':['No se modificó el sistema original ni una vida actual.','M306 conserva elIDqueued real; M307 conserva el prefijo común y dos futuros separados; M308 conserva el panel primero y la distinción de retención frente a trabajo.'],'native_started':False}
(W/'sector.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({'mechanisms':len(records),'variants':sum(len(x['variants']) for x in records),'store_bytes':(S/'almacen/CONTENIDOS.jsonl.gz').stat().st_size}))
